"""Solidity error ABI 解析、selector 与 revert data 编解码。

- :func:`parse_error_abi`：解析 ABI JSON 字符串或等价条目数组，只消费
  ``type == "error"`` 的条目，按声明顺序返回不可变
  :class:`ErrorDefinition`；function / event / constructor / receive /
  fallback 条目跳过不解析。
- :func:`canonical_error_signature`：返回 ``Name(type1,type2,...)`` 形式
  的规范错误签名（参数名不参与）。
- :func:`error_selector`：返回 ``keccak256(规范签名)[:4]`` 的四字节
  selector（bytes）。
- :func:`encode_error_data`：按错误名（无重载时）或规范签名选择 error，
  按 inputs 声明顺序把 list/tuple 实参编码为 ``selector + ABI(参数
  tuple)`` 的完整 revert data，返回 :class:`EncodedErrorData`。
- :func:`decode_error_data`：按 revert data 前四字节 selector 定位
  error，再严格解码参数 tuple，返回 :class:`DecodedErrorData`，携带
  名称、规范类型与值 tuple；无参数 error 的 revert data 即四字节
  selector，解码为空 tuple。

错误约定：

- 元数据非法（ABI 根不是数组、error 条目缺 name/type/inputs、标识符
  非法、参数类型字符串无法解析、规范签名重复等）抛
  :class:`abi_kit.AbiMetadataError`；
- 错误名或规范签名无匹配抛 :class:`abi_kit.AbiErrorNotFoundError`；
- 只给错误名但同名重载不止一个、无法唯一选择抛
  :class:`abi_kit.AbiErrorOverloadError`；
- revert data 少于四字节抛 :class:`abi_kit.AbiErrorDataLengthError`；
- selector 匹配不到任何 error 抛 :class:`abi_kit.AbiErrorSelectorError`；
- 实参不能按声明类型编码、或参数区不能按声明类型严格解码抛
  :class:`abi_kit.ABIValueError`；
- 参数消费完后仍有尾随字节抛 :class:`abi_kit.AbiErrorTrailingDataError`；
- revert data 不是 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串抛
  :class:`abi_kit.ABIValueError`。
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from ._codec import _decode, _encode
from ._event import _build_type, _is_identifier
from ._exceptions import (
    AbiErrorDataLengthError,
    AbiErrorNotFoundError,
    AbiErrorOverloadError,
    AbiErrorSelectorError,
    AbiErrorTrailingDataError,
    AbiEventError,
    AbiMetadataError,
    ABITypeError,
    ABIValueError,
)
from ._format import format_abi_type
from ._keccak import keccak_256
from ._types import ABIType, TupleType

_SELECTOR_LEN = 4
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

#: error 路径跳过但允许保留在 ABI 中的非 error 条目类型；这些条目的合法性
#: 由各自入口（如函数、事件路径）负责，本模块不解析。
_NON_ERROR_ENTRY_TYPES = frozenset(
    ("function", "event", "constructor", "receive", "fallback")
)


# ---- 不可变定义与结果对象 -------------------------------------------------


@dataclass(frozen=True)
class ErrorArgument:
    """error 的单个参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象；
    - ``value``：解码结果中按值层口径还原的 Python 值；定义中为 None。
    """

    name: str
    abi_type: ABIType
    value: object = None

    @property
    def type(self) -> str:
        """规范 ABI 类型字符串（不含空白与参数名）。"""
        return format_abi_type(self.abi_type)


@dataclass(frozen=True)
class ErrorDefinition:
    """不可变 error 定义。

    - ``name``：非空 ASCII 错误标识符；
    - ``inputs``：按声明顺序保存的 :class:`ErrorArgument`。
    """

    name: str
    inputs: tuple[ErrorArgument, ...] = field(default=())


@dataclass(frozen=True)
class EncodedErrorData:
    """error revert data 编码结果。

    - ``error``：命中的 :class:`ErrorDefinition`；
    - ``selector``：四字节 selector（bytes）；
    - ``data``：``selector + 参数 ABI 编码`` 的完整 revert data。
    """

    error: ErrorDefinition
    selector: bytes
    data: bytes

    @property
    def error_name(self) -> str:
        """命中 error 的名称。"""
        return self.error.name

    @property
    def signature(self) -> str:
        """命中 error 的规范签名，如 ``InsufficientBalance(address,uint256)``。"""
        return canonical_error_signature(self.error)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def data_hex(self) -> str:
        """``"0x"`` 前缀的完整 revert data 十六进制字符串。"""
        return "0x" + self.data.hex()


@dataclass(frozen=True)
class DecodedErrorData:
    """error revert data 解码结果。

    - ``error``：selector 命中的 :class:`ErrorDefinition`；
    - ``selector``：revert data 前四字节（bytes）；
    - ``args``：按声明顺序排列的 :class:`ErrorArgument`，``value`` 为
      还原值。
    """

    error: ErrorDefinition
    selector: bytes
    args: tuple[ErrorArgument, ...] = field(default=())

    @property
    def error_name(self) -> str:
        """命中 error 的名称。"""
        return self.error.name

    @property
    def signature(self) -> str:
        """命中 error 的规范签名，如 ``InsufficientBalance(address,uint256)``。"""
        return canonical_error_signature(self.error)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def types(self) -> tuple[str, ...]:
        """按声明顺序排列的规范 ABI 类型字符串 tuple。"""
        return tuple(arg.type for arg in self.args)

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(arg.value for arg in self.args)


# ---- ABI 解析 -------------------------------------------------------------


def _metadata(message: str) -> AbiMetadataError:
    return AbiMetadataError(message)


def _parse_error_entry(entry: dict) -> ErrorDefinition:
    """从单个 ABI error 条目构造不可变错误定义。"""
    name = entry.get("name")
    if not _is_identifier(name):
        raise _metadata(f"error name 必须是非空 ASCII 标识符，得到 {name!r}")
    if "inputs" not in entry:
        raise _metadata(f"error {name!r} 缺少 inputs")
    inputs_node = entry["inputs"]
    if not isinstance(inputs_node, (list, tuple)):
        raise _metadata(f"error {name!r} 的 inputs 必须是数组")

    parameters: list[ErrorArgument] = []
    for node in inputs_node:
        if not isinstance(node, dict):
            raise _metadata(
                f"error {name!r} 的参数必须是 JSON 对象，"
                f"得到 {type(node).__name__}"
            )
        param_name = node.get("name", "")
        if not isinstance(param_name, str):
            raise _metadata(
                f"error {name!r} 的参数 name 必须是字符串，得到 {param_name!r}"
            )
        try:
            # 与事件、函数路径共用同一套 type + components 递归展开；其
            # 失败统一是事件层错误码，这里转译为 error 元数据错误。
            abi_type = _build_type(node)
        except (AbiEventError, ABITypeError) as exc:
            raise _metadata(f"error {name!r} 的参数类型非法：{exc}") from None
        parameters.append(ErrorArgument(param_name, abi_type))
    return ErrorDefinition(name, tuple(parameters))


def parse_error_abi(abi) -> tuple[ErrorDefinition, ...]:
    """解析 ABI，返回其中全部 error 条目的不可变定义。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只消费 ``type == "error"`` 的条目，
    按声明顺序返回；function、event、constructor、receive、fallback 等
    其他条目原样保留在 ABI 中但不解析、不影响 error 路径。error 条目的
    ``inputs`` 必填；签名只由 name 与 inputs 的规范类型构成，参数名不
    参与。任何 error 元数据非法（含规范签名重复）抛
    :class:`abi_kit.AbiMetadataError`。
    """
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _metadata(f"ABI JSON 解析失败：{exc}") from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _metadata(
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}"
        )

    if not isinstance(root, (list, tuple)):
        raise _metadata("ABI 必须是条目数组，JSON 根不能是对象或标量")

    errors: list[ErrorDefinition] = []
    for entry in root:
        if not isinstance(entry, dict):
            raise _metadata(
                f"ABI 条目必须是 JSON 对象，得到 {type(entry).__name__}"
            )
        entry_type = entry.get("type")
        # function/event/constructor/receive/fallback 条目保留在 ABI 中供
        # 各自入口使用，error 路径跳过且不校验；缺 type 或未知条目类型属
        # 元数据非法，统一抛 AbiMetadataError。
        if entry_type == "error":
            errors.append(_parse_error_entry(entry))
        elif entry_type in _NON_ERROR_ENTRY_TYPES:
            continue
        else:
            raise _metadata(
                f"ABI 条目缺少 type 或带有未知类型 {entry_type!r}，"
                "合法值为 function/event/constructor/error/receive/fallback"
            )

    seen: set[str] = set()
    for error in errors:
        signature = canonical_error_signature(error)
        if signature in seen:
            raise _metadata(f"error 规范签名重复：{signature!r}")
        seen.add(signature)
    return tuple(errors)


# ---- 规范签名与 selector --------------------------------------------------


def canonical_error_signature(error: ErrorDefinition) -> str:
    """返回规范错误签名 ``Name(type1,type2,...)``。

    参数名不参与签名；tuple 输出为 ``(t1,t2)``，数组保留 ``[]``/``[n]``
    后缀。
    """
    if not isinstance(error, ErrorDefinition):
        raise _metadata(
            f"需要 ErrorDefinition，得到 {type(error).__name__}"
        )
    canonical = ",".join(format_abi_type(p.abi_type) for p in error.inputs)
    return f"{error.name}({canonical})"


def error_selector(error: ErrorDefinition) -> bytes:
    """返回 error 四字节 selector：``keccak256(规范签名)[:4]``。"""
    signature = canonical_error_signature(error)
    try:
        digest = keccak_256(signature.encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise _metadata(f"规范签名无法生成 selector：{exc}") from None
    return digest[:_SELECTOR_LEN]


# ---- 选择 error -----------------------------------------------------------


def _resolve_error(errors: tuple[ErrorDefinition, ...], key) -> ErrorDefinition:
    """按错误名或规范签名在已解析 error 中唯一定位。"""
    if not isinstance(key, str) or not key:
        raise _metadata(f"错误名或规范签名必须是非空字符串，得到 {key!r}")

    if "(" in key or ")" in key:
        for error in errors:
            if canonical_error_signature(error) == key:
                return error
        raise AbiErrorNotFoundError(
            f"ABI 中找不到规范签名为 {key!r} 的 error"
        )

    if not _is_identifier(key):
        raise _metadata(f"非法错误名：{key!r}")

    candidates = [error for error in errors if error.name == key]
    if not candidates:
        raise AbiErrorNotFoundError(f"ABI 中找不到 error {key!r}")
    if len(candidates) > 1:
        signatures = ", ".join(
            canonical_error_signature(error) for error in candidates
        )
        raise AbiErrorOverloadError(
            f"error {key!r} 存在 {len(candidates)} 个重载，无法唯一选择，"
            f"请改用规范签名之一：{signatures}"
        )
    return candidates[0]


# ---- revert data 编解码 ---------------------------------------------------


def _coerce_error_data(data) -> bytes:
    """把 bytes 或可选 0x 前缀的偶数位十六进制字符串规范化为 bytes。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise ABIValueError(
                "revert data 必须是可选 0x 前缀的偶数位十六进制字符串"
            )
        return bytes.fromhex(text)
    raise ABIValueError(
        f"revert data 必须是 bytes 或十六进制 str，得到 {type(data).__name__}"
    )


def _input_types(error: ErrorDefinition) -> TupleType:
    return TupleType(tuple(parameter.abi_type for parameter in error.inputs))


def encode_error_data(abi, error_name, args=None) -> EncodedErrorData:
    """编码一次 error revert data。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``error_name`` 接受
    错误名（ABI 中无同名重载时）或规范错误签名
    （``InsufficientBalance(address,uint256)``）；``args`` 为按 inputs
    声明顺序排列的实参列表（list/tuple），无参 error 可省略。

    返回 :class:`EncodedErrorData`，其中 ``selector`` 为四字节 bytes，
    ``data`` 为 ``selector + 参数 tuple 的 ABI 编码`` 的完整 revert
    data。实参不能按声明类型编码（含数量不符）抛
    :class:`abi_kit.ABIValueError`。
    """
    errors = parse_error_abi(abi)
    error = _resolve_error(errors, error_name)

    if args is None:
        values = ()
    elif isinstance(args, (list, tuple)):
        values = tuple(args)
    else:
        raise ABIValueError(
            f"实参列表必须是 list 或 tuple，得到 {type(args).__name__}"
        )

    payload = _encode(_input_types(error), values)
    selector = error_selector(error)
    return EncodedErrorData(error, selector, selector + payload)


def decode_error_data(abi, data) -> DecodedErrorData:
    """解码完整 error revert data。

    ``data`` 接受 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串，前四
    字节必须是 ABI 中某个 error 的 selector；其后按该 error inputs 组成
    的 tuple 严格 ABI 解码。返回 :class:`DecodedErrorData`，携带 error
    定义、selector、规范签名（属性）与按声明顺序排列的带类型标注参数；
    ``values`` 属性给出等价的纯值 tuple。无参数 error 的 revert data 即
    四字节 selector，解码为空 tuple。

    data 类型或十六进制非法抛 :class:`abi_kit.ABIValueError`；少于四字节
    抛 :class:`abi_kit.AbiErrorDataLengthError`；selector 无匹配抛
    :class:`abi_kit.AbiErrorSelectorError`；参数区不能严格解码抛
    :class:`abi_kit.ABIValueError`；解码后仍有尾随字节抛
    :class:`abi_kit.AbiErrorTrailingDataError`。
    """
    errors = parse_error_abi(abi)
    raw = _coerce_error_data(data)

    if len(raw) < _SELECTOR_LEN:
        raise AbiErrorDataLengthError(
            f"revert data 长度必须至少为 {_SELECTOR_LEN} 字节以容纳 "
            f"selector，得到 {len(raw)} 字节"
        )
    selector = raw[:_SELECTOR_LEN]

    matches = [error for error in errors if error_selector(error) == selector]
    if not matches:
        raise AbiErrorSelectorError(
            f"selector 0x{selector.hex()} 在 ABI 中匹配不到任何 error"
        )
    error = matches[0]

    payload = raw[_SELECTOR_LEN:]
    bound = len(payload)
    values, end = _decode(_input_types(error), payload, 0, bound)
    if end != bound:
        raise AbiErrorTrailingDataError(
            f"参数解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    arguments = tuple(
        ErrorArgument(parameter.name, parameter.abi_type, value)
        for parameter, value in zip(error.inputs, values)
    )
    return DecodedErrorData(error, selector, arguments)

"""函数 ABI 解析、selector 与函数调用数据（calldata）编解码。

- :func:`parse_function_abi`：解析 ABI JSON 字符串或等价条目数组，只消费
  ``type == "function"`` 的条目，返回不可变 :class:`FunctionDefinition`；
  event / constructor / error / receive / fallback 条目跳过不解析。
- :func:`canonical_function_signature`：返回
  ``name(type1,type2,...)`` 形式的规范函数签名（参数名不参与）。
- :func:`function_selector`：返回
  ``keccak256(canonical_signature)[:4]`` 的四字节 selector。
- :func:`encode_function_call`：按函数名（无重载时）或规范签名选择函数，
  按公开参数顺序编码实参，返回 selector 与 ``selector + ABI(参数 tuple)``
  的完整 calldata。
- :func:`decode_function_call`：按 calldata 前四字节还原函数，再严格解码
  参数 tuple，返回函数标识、规范签名与带类型标注的参数结果。
- :func:`encode_function_result` / :func:`decode_function_result`：按
  函数 outputs 声明编解码返回值；outputs 不参与 selector 与 calldata，
  无 outputs 的函数编码为 ``b""``。

``encodeFunctionCall`` / ``decodeFunctionCall`` 与
``encodeFunctionResult`` / ``decodeFunctionResult`` 是上述入口的
camelCase 别名。

错误约定：

- 元数据非法（ABI 根不是数组、function 条目缺 name/type/inputs、
  标识符非法、参数类型字符串无法解析等）抛
  :class:`abi_kit.AbiMetadataError`；
- 函数名或规范签名无匹配抛 :class:`abi_kit.AbiFunctionNotFoundError`；
- 只给函数名但同名重载不止一个、无法唯一选择抛
  :class:`abi_kit.AbiOverloadError`；
- selector 匹配不到任何函数抛 :class:`abi_kit.AbiSelectorError`；
- calldata 少于四字节抛 :class:`abi_kit.AbiCalldataLengthError`；
- 实参不能按声明类型编码、或参数区不能按声明类型严格解码抛
  :class:`abi_kit.ABIValueError`；
- 参数消费完后仍有尾随字节抛 :class:`abi_kit.AbiTrailingDataError`；
- 返回值数量或类型与 outputs 声明不符、返回值数据不能严格解码抛
  :class:`abi_kit.ABIValueError`；返回值解码后仍有尾随字节同样抛
  :class:`abi_kit.AbiTrailingDataError`。
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from ._codec import _decode, _encode
from ._event import _build_type, _is_identifier
from ._exceptions import (
    AbiCalldataLengthError,
    AbiEventError,
    AbiFunctionNotFoundError,
    AbiMetadataError,
    AbiOverloadError,
    AbiSelectorError,
    AbiTrailingDataError,
    ABITypeError,
    ABIValueError,
)
from ._format import format_abi_type
from ._keccak import keccak_256
from ._types import ABIType, TupleType

_SELECTOR_LEN = 4

#: 函数路径跳过但允许保留在 ABI 中的非函数条目类型；这些条目的合法性
#: 由各自入口（如事件路径）负责，本模块不解析。
_NON_FUNCTION_ENTRY_TYPES = frozenset(
    ("event", "constructor", "error", "receive", "fallback")
)


# ---- 不可变定义与结果对象 -------------------------------------------------


@dataclass(frozen=True)
class FunctionParameter:
    """函数的单个公开参数（声明顺序保留）。

    - ``name``：ABI JSON 中的参数名，缺省为空串；
    - ``abi_type``：由 ``type`` + ``components`` 展开得到的类型对象。
    """

    name: str
    abi_type: ABIType


@dataclass(frozen=True)
class FunctionDefinition:
    """不可变函数定义。

    - ``name``：非空 ASCII 函数标识符；
    - ``inputs``：按声明顺序保存的 :class:`FunctionParameter`；
    - ``outputs``：按声明顺序保存的返回值 :class:`FunctionParameter`
      （缺省为空）；outputs 不参与规范签名、selector 与 calldata。
    """

    name: str
    inputs: tuple[FunctionParameter, ...] = field(default=())
    outputs: tuple[FunctionParameter, ...] = field(default=())


@dataclass(frozen=True)
class EncodedFunctionCall:
    """函数调用编码结果。

    - ``function``：命中的 :class:`FunctionDefinition`；
    - ``selector``：四字节 selector（bytes）；
    - ``calldata``：``selector + 参数 ABI 编码`` 的完整调用数据。
    """

    function: FunctionDefinition
    selector: bytes
    calldata: bytes

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名，如 ``transfer(address,uint256)``。"""
        return canonical_function_signature(self.function)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def calldata_hex(self) -> str:
        """``"0x"`` 前缀的完整 calldata 十六进制字符串。"""
        return "0x" + self.calldata.hex()


@dataclass(frozen=True)
class FunctionArgument:
    """解码后带类型标注的单个实参。

    - ``name``：声明的参数名，未命名时为空串；
    - ``type``：规范 ABI 类型字符串（不含空白与参数名）；
    - ``value``：按值层口径还原的 Python 值。
    """

    name: str
    type: str
    value: object


@dataclass(frozen=True)
class DecodedFunctionCall:
    """函数调用解码结果。

    - ``function``：selector 命中的 :class:`FunctionDefinition`；
    - ``selector``：calldata 前四字节（bytes）；
    - ``args``：按声明顺序排列的 :class:`FunctionArgument`。
    """

    function: FunctionDefinition
    selector: bytes
    args: tuple[FunctionArgument, ...] = field(default=())

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名，如 ``transfer(address,uint256)``。"""
        return canonical_function_signature(self.function)

    @property
    def selector_hex(self) -> str:
        """``"0x"`` + 8 个小写十六进制字符形式的 selector。"""
        return "0x" + self.selector.hex()

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(arg.value for arg in self.args)


@dataclass(frozen=True)
class EncodedFunctionResult:
    """函数返回值编码结果。

    - ``function``：命中的 :class:`FunctionDefinition`；
    - ``data``：outputs tuple 的 ABI 编码，无 outputs 时为 ``b""``。
    """

    function: FunctionDefinition
    data: bytes

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名（outputs 不参与），如 ``balanceOf(address)``。"""
        return canonical_function_signature(self.function)

    @property
    def data_hex(self) -> str:
        """``"0x"`` 前缀的小写十六进制编码结果。"""
        return "0x" + self.data.hex()


@dataclass(frozen=True)
class DecodedFunctionResult:
    """函数返回值解码结果。

    - ``function``：命中的 :class:`FunctionDefinition`；
    - ``outputs``：按声明顺序排列的 :class:`FunctionArgument`，``name``
      为声明的返回值名（未命名为空串），``type`` 为规范 ABI 类型字符串。
    """

    function: FunctionDefinition
    outputs: tuple[FunctionArgument, ...] = field(default=())

    @property
    def function_name(self) -> str:
        """命中函数的名称。"""
        return self.function.name

    @property
    def signature(self) -> str:
        """命中函数的规范签名（outputs 不参与），如 ``balanceOf(address)``。"""
        return canonical_function_signature(self.function)

    @property
    def values(self) -> tuple:
        """按声明顺序去掉类型标注后的纯值 tuple。"""
        return tuple(output.value for output in self.outputs)


# ---- ABI 解析 -------------------------------------------------------------


def _metadata(message: str) -> AbiMetadataError:
    return AbiMetadataError(message)


def _parse_parameters(name: str, nodes, noun: str) -> tuple[FunctionParameter, ...]:
    """把 inputs/outputs 节点数组展开为 :class:`FunctionParameter` tuple。"""
    parameters: list[FunctionParameter] = []
    for node in nodes:
        if not isinstance(node, dict):
            raise _metadata(
                f"函数 {name!r} 的{noun}必须是 JSON 对象，得到 {type(node).__name__}"
            )
        param_name = node.get("name", "")
        if not isinstance(param_name, str):
            raise _metadata(
                f"函数 {name!r} 的{noun} name 必须是字符串，得到 {param_name!r}"
            )
        try:
            # 与事件路径共用同一套 type + components 递归展开；其失败
            # 统一是事件层错误码，这里转译为函数元数据错误。
            abi_type = _build_type(node)
        except (AbiEventError, ABITypeError) as exc:
            raise _metadata(f"函数 {name!r} 的{noun}类型非法：{exc}") from None
        parameters.append(FunctionParameter(param_name, abi_type))
    return tuple(parameters)


def _parse_function_entry(entry: dict) -> FunctionDefinition:
    """从单个 ABI function 条目构造不可变函数定义。"""
    name = entry.get("name")
    if not _is_identifier(name):
        raise _metadata(f"函数 name 必须是非空 ASCII 标识符，得到 {name!r}")
    if "inputs" not in entry:
        raise _metadata(f"函数 {name!r} 缺少 inputs")
    inputs_node = entry["inputs"]
    if not isinstance(inputs_node, (list, tuple)):
        raise _metadata(f"函数 {name!r} 的 inputs 必须是数组")
    inputs = _parse_parameters(name, inputs_node, "参数")

    # outputs 缺省视为无返回值；存在时必须是合法参数描述数组。
    outputs_node = entry.get("outputs", [])
    if not isinstance(outputs_node, (list, tuple)):
        raise _metadata(f"函数 {name!r} 的 outputs 必须是数组")
    outputs = _parse_parameters(name, outputs_node, "返回值")

    return FunctionDefinition(name, inputs, outputs)


def parse_function_abi(abi) -> tuple[FunctionDefinition, ...]:
    """解析 ABI，返回其中全部 function 条目的不可变定义。

    ``abi`` 接受 ABI JSON 字符串（:func:`json.loads` 口径）或等价的
    Python 条目数组（list/tuple）。只消费 ``type == "function"`` 的条目；
    event、constructor、error、receive、fallback 等其他条目原样保留在
    ABI 中但不解析、不影响函数路径。函数条目的 ``inputs`` 必填，
    ``outputs`` 缺省视为无返回值。任何函数元数据非法抛
    :class:`abi_kit.AbiMetadataError`。
    """
    if isinstance(abi, str):
        try:
            root = json.loads(abi)
        except (json.JSONDecodeError, ValueError) as exc:
            raise _metadata(f"ABI JSON 解析失败：{exc}") from None
    elif isinstance(abi, (list, tuple)):
        root = abi
    else:
        raise _metadata(
            f"ABI 必须是 JSON 字符串或条目数组，得到 {type(abi).__name__}"
        )

    if not isinstance(root, (list, tuple)):
        raise _metadata("ABI 必须是条目数组，JSON 根不能是对象或标量")

    functions: list[FunctionDefinition] = []
    for entry in root:
        if not isinstance(entry, dict):
            raise _metadata(
                f"ABI 条目必须是 JSON 对象，得到 {type(entry).__name__}"
            )
        entry_type = entry.get("type")
        # event/constructor/error/receive/fallback 条目保留在 ABI 中供
        # 各自入口使用，函数路径跳过且不校验；缺 type 或未知条目类型属
        # 元数据非法，统一抛 AbiMetadataError。
        if entry_type == "function":
            functions.append(_parse_function_entry(entry))
        elif entry_type in _NON_FUNCTION_ENTRY_TYPES:
            continue
        else:
            raise _metadata(
                f"ABI 条目缺少 type 或带有未知类型 {entry_type!r}，"
                "合法值为 function/event/constructor/error/receive/fallback"
            )
    return tuple(functions)


# ---- 规范签名与 selector --------------------------------------------------


def canonical_function_signature(function: FunctionDefinition) -> str:
    """返回规范函数签名 ``name(type1,type2,...)``。

    参数名不参与签名；tuple 输出为 ``(t1,t2)``，数组保留 ``[]``/``[n]``
    后缀。
    """
    if not isinstance(function, FunctionDefinition):
        raise _metadata(
            f"需要 FunctionDefinition，得到 {type(function).__name__}"
        )
    canonical = ",".join(format_abi_type(p.abi_type) for p in function.inputs)
    return f"{function.name}({canonical})"


def function_selector(function: FunctionDefinition) -> bytes:
    """返回函数四字节 selector：``keccak256(规范签名)[:4]``。"""
    signature = canonical_function_signature(function)
    try:
        digest = keccak_256(signature.encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise _metadata(f"规范签名无法生成 selector：{exc}") from None
    return digest[:_SELECTOR_LEN]


# ---- 选择函数 -------------------------------------------------------------


def _resolve_function(
    functions: tuple[FunctionDefinition, ...], key
) -> FunctionDefinition:
    """按函数名或规范签名在已解析函数中唯一定位。"""
    if not isinstance(key, str) or not key:
        raise _metadata(f"函数名或规范签名必须是非空字符串，得到 {key!r}")

    if "(" in key or ")" in key:
        for function in functions:
            if canonical_function_signature(function) == key:
                return function
        raise AbiFunctionNotFoundError(
            f"ABI 中找不到规范签名为 {key!r} 的函数"
        )

    if not _is_identifier(key):
        raise _metadata(f"非法函数名：{key!r}")

    candidates = [function for function in functions if function.name == key]
    if not candidates:
        raise AbiFunctionNotFoundError(f"ABI 中找不到函数 {key!r}")
    if len(candidates) > 1:
        signatures = ", ".join(
            canonical_function_signature(function) for function in candidates
        )
        raise AbiOverloadError(
            f"函数 {key!r} 存在 {len(candidates)} 个重载，无法唯一选择，"
            f"请改用规范签名之一：{signatures}"
        )
    return candidates[0]


# ---- calldata 编解码 ------------------------------------------------------


def _coerce_calldata(calldata) -> bytes:
    """把 bytes 或可选 0x 前缀的十六进制字符串规范化为 bytes。"""
    if isinstance(calldata, bytes):
        return calldata
    if isinstance(calldata, str):
        text = calldata[2:] if calldata[:2] in ("0x", "0X") else calldata
        try:
            return bytes.fromhex(text)
        except ValueError as exc:
            raise ABIValueError(f"calldata 十六进制非法：{exc}") from exc
    raise ABIValueError(
        f"calldata 必须是 bytes 或十六进制 str，得到 {type(calldata).__name__}"
    )


def encode_function_call(
    abi, function_name, args=None
) -> EncodedFunctionCall:
    """编码一次函数调用。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``function_name`` 接受
    函数名（ABI 中无同名重载时）或规范函数签名
    （``transfer(address,uint256)``）；``args`` 为按公开参数顺序排列的
    实参列表（list/tuple），无参函数可省略。

    返回 :class:`EncodedFunctionCall`，其中 ``selector`` 为四字节
    bytes，``calldata`` 为 ``selector + 参数 tuple 的 ABI 编码``。
    实参不能按声明类型编码（含数量不符）抛 :class:`abi_kit.ABIValueError`。
    """
    functions = parse_function_abi(abi)
    function = _resolve_function(functions, function_name)

    if args is None:
        values = ()
    elif isinstance(args, (list, tuple)):
        values = tuple(args)
    else:
        raise ABIValueError(
            f"实参列表必须是 list 或 tuple，得到 {type(args).__name__}"
        )

    parameter_types = TupleType(
        tuple(parameter.abi_type for parameter in function.inputs)
    )
    payload = _encode(parameter_types, values)
    selector = function_selector(function)
    return EncodedFunctionCall(function, selector, selector + payload)


def decode_function_call(abi, calldata) -> DecodedFunctionCall:
    """解码完整函数调用数据。

    ``calldata`` 接受 bytes 或可选 ``0x`` 前缀的十六进制字符串，前四字节
    必须是 ABI 中某个函数的 selector；其后按该函数公开参数组成的 tuple
    严格 ABI 解码。返回 :class:`DecodedFunctionCall`，携带函数定义、
    selector、规范签名（属性）与按声明顺序排列的带类型标注实参。

    calldata 少于四字节抛 :class:`abi_kit.AbiCalldataLengthError`；
    selector 无匹配抛 :class:`abi_kit.AbiSelectorError`；参数区不能严格
    解码抛 :class:`abi_kit.ABIValueError`；解码后仍有尾随字节抛
    :class:`abi_kit.AbiTrailingDataError`。
    """
    functions = parse_function_abi(abi)
    raw = _coerce_calldata(calldata)

    if len(raw) < _SELECTOR_LEN:
        raise AbiCalldataLengthError(
            f"calldata 长度必须至少为 {_SELECTOR_LEN} 字节以容纳 selector，"
            f"得到 {len(raw)} 字节"
        )
    selector = raw[:_SELECTOR_LEN]

    matches = [
        function
        for function in functions
        if function_selector(function) == selector
    ]
    if not matches:
        raise AbiSelectorError(
            f"selector 0x{selector.hex()} 在 ABI 中匹配不到任何函数"
        )
    function = matches[0]

    parameter_types = TupleType(
        tuple(parameter.abi_type for parameter in function.inputs)
    )
    payload = raw[_SELECTOR_LEN:]
    bound = len(payload)
    try:
        values, end = _decode(parameter_types, payload, 0, bound)
    except ABIValueError:
        raise
    if end != bound:
        raise AbiTrailingDataError(
            f"参数解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    arguments = tuple(
        FunctionArgument(
            parameter.name, format_abi_type(parameter.abi_type), value
        )
        for parameter, value in zip(function.inputs, values)
    )
    return DecodedFunctionCall(function, selector, arguments)


# camelCase 公开别名。
encodeFunctionCall = encode_function_call
decodeFunctionCall = decode_function_call


# ---- 返回值（outputs）编解码 ----------------------------------------------


_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


def _coerce_result_data(data) -> bytes:
    """把 bytes 或可选 0x 前缀的偶数位十六进制字符串规范化为 bytes。"""
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        if len(text) % 2 or any(c not in _HEX_DIGITS for c in text):
            raise ABIValueError(
                "返回值数据必须是可选 0x 前缀的偶数位十六进制字符串"
            )
        return bytes.fromhex(text)
    raise ABIValueError(
        f"返回值数据必须是 bytes 或十六进制 str，得到 {type(data).__name__}"
    )


def _output_types(function: FunctionDefinition) -> TupleType:
    return TupleType(tuple(output.abi_type for output in function.outputs))


def encode_function_result(
    abi, function_name, values=None
) -> EncodedFunctionResult:
    """按函数 outputs 声明编码返回值。

    ``abi`` 接受 ABI JSON 字符串或等价条目数组；``function_name`` 接受
    函数名（ABI 中无同名重载时）或规范函数签名；``values`` 为按 outputs
    声明顺序排列的返回值列表（list/tuple），无 outputs 的函数只接受空
    序列（或可省略），编码结果为 ``b""``。

    返回 :class:`EncodedFunctionResult`，其中 ``data`` 为 outputs tuple
    的标准 ABI 编码，``data_hex`` 为其小写 ``"0x"`` 前缀十六进制形式。
    数量或类型与 outputs 声明不符抛 :class:`abi_kit.ABIValueError`。
    """
    functions = parse_function_abi(abi)
    function = _resolve_function(functions, function_name)

    if values is None:
        items = ()
    elif isinstance(values, (list, tuple)):
        items = tuple(values)
    else:
        raise ABIValueError(
            f"返回值列表必须是 list 或 tuple，得到 {type(values).__name__}"
        )

    data = _encode(_output_types(function), items)
    return EncodedFunctionResult(function, data)


def decode_function_result(abi, function_name, data) -> DecodedFunctionResult:
    """按函数 outputs 声明严格解码返回值数据。

    ``abi`` 与 ``function_name`` 口径同 :func:`encode_function_result`；
    ``data`` 接受 bytes 或可选 ``0x`` 前缀的偶数位十六进制字符串，按该
    函数 outputs 组成的 tuple 严格 ABI 解码。返回
    :class:`DecodedFunctionResult`，携带函数定义与按声明顺序排列的带
    类型标注返回值；``values`` 属性给出等价的纯值 tuple。无 outputs 的
    函数只接受 ``b""``，往返得到空 tuple。

    输入类型或十六进制非法、长度不足及 head/tail、偏移、长度、补零、
    UTF-8、定长数组约束不满足抛 :class:`abi_kit.ABIValueError`；解码后
    仍有尾随字节抛 :class:`abi_kit.AbiTrailingDataError`。
    """
    functions = parse_function_abi(abi)
    function = _resolve_function(functions, function_name)
    raw = _coerce_result_data(data)

    bound = len(raw)
    values, end = _decode(_output_types(function), raw, 0, bound)
    if end != bound:
        raise AbiTrailingDataError(
            f"返回值解码完成后仍有 {bound - end} 字节尾随数据未被消费"
        )

    outputs = tuple(
        FunctionArgument(output.name, format_abi_type(output.abi_type), value)
        for output, value in zip(function.outputs, values)
    )
    return DecodedFunctionResult(function, outputs)


# camelCase 公开别名。
encodeFunctionResult = encode_function_result
decodeFunctionResult = decode_function_result

"""Solidity ABI 值层编解码。

遵循 Solidity ABI 的 head/tail 布局：

- 静态类型直接占用一个或多个 32 字节字；
- 动态类型（string / 动态 bytes / 动态数组 / 含动态成员的定长数组
  或元组）在 head 中放 32 字节偏移，实体置于 tail；
- 动态数组实体以长度字开头，随后是与“等长定长数组”相同的块；
- 偏移均相对于所属块（数组元素块的起点在长度字之后）。

解码采用严格规范：块内动态成员必须按声明顺序紧密排列（偏移恰好指向前
一动态实体的终点），不允许空洞、重叠或倒序；所有填充字节必须为零。

值口径：
- uintM/intM -> int，bool -> bool，string -> str；
- bytes/bytesM -> bytes；
- address -> 小写 ``"0x" + 40 个十六进制字符``；
- 数组 -> list，元组 -> tuple。

所有值不匹配、非法编码与不适用的类型对象统一抛出
:class:`abi_kit.ABIValueError`；类型层错误仍属
:class:`abi_kit.ABITypeError`，本模块不改变其适用范围。
"""

from __future__ import annotations

from ._exceptions import ABIValueError
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WORD = 32


# ---- 类型静态性质 --------------------------------------------------------


def _is_dynamic(abi_type: ABIType) -> bool:
    if isinstance(abi_type, ElementaryType):
        return abi_type.kind == "string" or (
            abi_type.kind == "bytes" and abi_type.byte_size is None
        )
    if isinstance(abi_type, ArrayType):
        return abi_type.length is None or _is_dynamic(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return any(_is_dynamic(c) for c in abi_type.components)
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _static_size(abi_type: ABIType) -> int:
    """静态类型作为一个整体占用的字节数（仅对非动态类型调用）。"""
    if isinstance(abi_type, ElementaryType):
        return _WORD
    if isinstance(abi_type, ArrayType):
        return abi_type.length * _static_size(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return sum(_static_size(c) for c in abi_type.components)
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _head_slot(abi_type: ABIType) -> int:
    """该类型作为块成员时在 head 中占用的字节数。"""
    return _WORD if _is_dynamic(abi_type) else _static_size(abi_type)


# ---- 编码 ----------------------------------------------------------------


def _uint_word(value: int) -> bytes:
    return value.to_bytes(_WORD, "big", signed=False)


def _address_bytes(value) -> bytes:
    if not isinstance(value, str):
        raise ABIValueError(f"address 需要十六进制字符串，得到 {type(value).__name__}")
    text = value[2:] if value.startswith(("0x", "0X")) else value
    if len(text) != 40 or any(c not in "0123456789abcdefABCDEF" for c in text):
        raise ABIValueError(
            f"address 必须是带或不带 0x 前缀的 40 位十六进制字符串：{value!r}"
        )
    return bytes.fromhex(text)


def _len_prefixed(payload: bytes) -> bytes:
    padding = (-len(payload)) % _WORD
    return _uint_word(len(payload)) + payload + b"\x00" * padding


def _encode_elementary(t: ElementaryType, value) -> bytes:
    kind = t.kind
    if kind == "uint":
        if isinstance(value, bool) or not isinstance(value, int):
            raise ABIValueError(
                f"uint{t.bit_size} 需要 int，得到 {type(value).__name__}"
            )
        bits = t.bit_size
        if not 0 <= value < 1 << bits:
            raise ABIValueError(f"uint{bits} 超出范围 [0, {2**bits - 1}]：{value}")
        return _uint_word(value)
    if kind == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            raise ABIValueError(
                f"int{t.bit_size} 需要 int，得到 {type(value).__name__}"
            )
        bits = t.bit_size
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= value <= high:
            raise ABIValueError(f"int{bits} 超出补码范围 [{low}, {high}]：{value}")
        return value.to_bytes(_WORD, "big", signed=True)
    if kind == "address":
        return b"\x00" * 12 + _address_bytes(value)
    if kind == "bool":
        if not isinstance(value, bool):
            raise ABIValueError(f"bool 需要 Python bool，得到 {type(value).__name__}")
        return _uint_word(1 if value else 0)
    if kind == "string":
        if not isinstance(value, str):
            raise ABIValueError(f"string 需要 str，得到 {type(value).__name__}")
        try:
            payload = value.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ABIValueError(f"字符串无法编码为 UTF-8：{exc}") from exc
        return _len_prefixed(payload)
    # bytes（动态）或 bytesM
    if not isinstance(value, bytes):
        label = "bytes" if t.byte_size is None else f"bytes{t.byte_size}"
        raise ABIValueError(f"{label} 需要 bytes，得到 {type(value).__name__}")
    if t.byte_size is None:
        return _len_prefixed(value)
    if len(value) != t.byte_size:
        raise ABIValueError(
            f"bytes{t.byte_size} 需要恰好 {t.byte_size} 字节，得到 {len(value)} 字节"
        )
    return value + b"\x00" * (_WORD - t.byte_size)


def _encode_block(member_types: list[ABIType], values: list) -> bytes:
    """编码一个 head/tail 块（元组成员或一组同构数组元素）。

    动态成员在 head 中的偏移相对于本块起点，动态实体按声明顺序紧密
    拼接在整块 head 之后。
    """
    head_chunks: list[bytes] = []
    dynamic_entities: list[tuple[int, bytes]] = []
    head_length = 0
    for index, (member_type, value) in enumerate(zip(member_types, values)):
        if _is_dynamic(member_type):
            head_chunks.append(b"\x00" * _WORD)
            dynamic_entities.append((index, _encode(member_type, value)))
        else:
            head_chunks.append(_encode(member_type, value))
        head_length += _head_slot(member_type)

    tail = bytearray()
    for index, entity in dynamic_entities:
        head_chunks[index] = _uint_word(head_length + len(tail))
        tail += entity
    return b"".join(head_chunks) + bytes(tail)


def _encode(abi_type: ABIType, value) -> bytes:
    """把值编码为一个自洽实体（动态类型即其 tail 实体）。"""
    if isinstance(abi_type, ElementaryType):
        return _encode_elementary(abi_type, value)
    if isinstance(abi_type, ArrayType):
        if not isinstance(value, list):
            raise ABIValueError(f"数组需要 list，得到 {type(value).__name__}")
        element_type = abi_type.element_type
        if abi_type.length is not None and len(value) != abi_type.length:
            raise ABIValueError(
                f"定长数组长度应为 {abi_type.length}，得到 {len(value)}"
            )
        block = _encode_block([element_type] * len(value), list(value))
        if abi_type.length is None:
            return _uint_word(len(value)) + block
        return block
    if isinstance(abi_type, TupleType):
        if not isinstance(value, tuple):
            raise ABIValueError(f"元组需要 tuple，得到 {type(value).__name__}")
        if len(value) != len(abi_type.components):
            raise ABIValueError(
                f"元组长度应为 {len(abi_type.components)}，得到 {len(value)}"
            )
        return _encode_block(list(abi_type.components), list(value))
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


# ---- 解码 ----------------------------------------------------------------


def _read_word(data: bytes, pos: int, bound: int) -> bytes:
    if pos < 0 or pos + _WORD > bound:
        raise ABIValueError("编码数据长度不足：缺少完整的 32 字节字")
    return data[pos:pos + _WORD]


def _decode_elementary(t: ElementaryType, data: bytes, pos: int, bound: int):
    """解码基础类型实体，返回 ``(值, 终点位置)``。"""
    kind = t.kind
    if kind == "string" or (kind == "bytes" and t.byte_size is None):
        length = int.from_bytes(_read_word(data, pos, bound), "big", signed=False)
        payload_start = pos + _WORD
        padded_length = ((length + _WORD - 1) // _WORD) * _WORD
        end = payload_start + padded_length
        if end > bound:
            raise ABIValueError("动态数据长度超出编码边界")
        payload_end = payload_start + length
        if data[payload_end:end] != b"\x00" * (end - payload_end):
            raise ABIValueError("动态数据尾部填充非零，编码不规范")
        payload = data[payload_start:payload_end]
        if kind == "string":
            try:
                value = payload.decode("utf-8")
            except UnicodeDecodeError as exc:
                raise ABIValueError(f"非法 UTF-8 字符串：{exc}") from exc
        else:
            value = payload
        return value, end

    word = _read_word(data, pos, bound)
    end = pos + _WORD
    if kind == "uint":
        value = int.from_bytes(word, "big", signed=False)
        if value >= 1 << t.bit_size:
            raise ABIValueError(f"uint{t.bit_size} 解码值越界：{value}")
        return value, end
    if kind == "int":
        value = int.from_bytes(word, "big", signed=True)
        bits = t.bit_size
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= value <= high:
            raise ABIValueError(f"int{bits} 解码值超出补码范围 [{low}, {high}]：{value}")
        return value, end
    if kind == "address":
        if word[:12] != b"\x00" * 12:
            raise ABIValueError("address 高位填充非零，超出 20 字节范围")
        return "0x" + word[12:].hex(), end
    if kind == "bool":
        if word == b"\x00" * _WORD:
            return False, end
        if word == b"\x00" * (_WORD - 1) + b"\x01":
            return True, end
        raise ABIValueError("非法布尔字：既非全 0 也非末尾字节为 1")
    # bytesM
    if word[t.byte_size:] != b"\x00" * (_WORD - t.byte_size):
        raise ABIValueError(f"bytes{t.byte_size} 尾部填充非零，编码不规范")
    return word[:t.byte_size], end


def _decode_block(
    member_types: list[ABIType], data: bytes, base: int, bound: int
):
    """解码一个 head/tail 块，返回 ``(按声明顺序的值列表, 块终点)``。

    动态成员的偏移必须恰好指向前一动态实体的终点（紧密排列），否则
    视为非法编码。
    """
    head_length = 0
    for member_type in member_types:
        head_length += _head_slot(member_type)
    head_end = base + head_length
    if head_end > bound:
        raise ABIValueError("编码数据长度不足：块 head 越界")

    values = [None] * len(member_types)
    cursor = head_end
    head_pos = base
    for index, member_type in enumerate(member_types):
        if _is_dynamic(member_type):
            offset = int.from_bytes(
                _read_word(data, head_pos, bound), "big", signed=False
            )
            target = base + offset
            if target != cursor:
                raise ABIValueError(
                    f"动态偏移非法：成员 {index} 应指向 {cursor}，实际指向 {target}"
                )
            values[index], cursor = _decode(member_type, data, target, bound)
        else:
            values[index], end = _decode(member_type, data, head_pos, bound)
            if end != head_pos + _static_size(member_type):
                raise ABIValueError("静态成员尺寸与声明不一致")
        head_pos += _head_slot(member_type)
    return values, cursor


def _decode(abi_type: ABIType, data: bytes, pos: int, bound: int):
    """从 ``pos`` 解码一个实体，返回 ``(值, 终点位置)``，不越过 bound。"""
    if isinstance(abi_type, ElementaryType):
        return _decode_elementary(abi_type, data, pos, bound)
    if isinstance(abi_type, ArrayType):
        element_type = abi_type.element_type
        if abi_type.length is None:
            count = int.from_bytes(_read_word(data, pos, bound), "big", signed=False)
            base = pos + _WORD
            if base > bound:
                raise ABIValueError("编码数据长度不足：动态数组缺少元素块")
        else:
            count = abi_type.length
            base = pos
        # 先按 head 尺寸拦截伪造的超大长度，避免成员列表内存放大。
        slot = _head_slot(element_type)
        remaining = bound - base
        if slot:
            if count > remaining // slot:
                raise ABIValueError("数组元素块越界：长度与数据不符")
            member_types = [element_type] * count
        elif count:
            # 零尺寸静态元素（如 ()）：实体不占字节，无法用剩余数据约束
            # 长度；仅需防止离谱的乘法分配。
            try:
                member_types = [element_type] * count
            except (MemoryError, OverflowError) as exc:
                raise ABIValueError("数组长度过大，超出可解码范围") from exc
        else:
            member_types = []
        values, end = _decode_block(member_types, data, base, bound)
        return values, end
    if isinstance(abi_type, TupleType):
        values, end = _decode_block(list(abi_type.components), data, pos, bound)
        return tuple(values), end
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


# ---- 公开入口 ------------------------------------------------------------


def encode_abi_value(abi_type: ABIType, value) -> bytes:
    """按 ``abi_type`` 把 Python 值编码为完整 ABI 编码 bytes。

    值与类型不匹配或类型对象不适用时抛出 :class:`abi_kit.ABIValueError`。
    """
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")
    return _encode(abi_type, value)


def decode_abi_value(abi_type: ABIType, data: bytes):
    """把完整 ABI 编码 bytes 解码回 Python 值。

    要求 ``data`` 恰好容纳一个值：长度不足、偏移越界、尾部残留、
    定长数组长度不符、非法布尔字、非法 UTF-8 或越界数值均抛出
    :class:`abi_kit.ABIValueError`。
    """
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")
    if not isinstance(data, bytes):
        raise ABIValueError(f"编码数据必须是 bytes，得到 {type(data).__name__}")

    bound = len(data)
    value, end = _decode(abi_type, data, 0, bound)
    if end != bound:
        raise ABIValueError(
            f"尾部残留 {bound - end} 字节：编码未被完整消费"
        )
    return value

